import React from 'react';
import {AbsoluteFill, Audio, Easing, Sequence, random, staticFile, useCurrentFrame} from 'remotion';
import {loadFont} from '@remotion/google-fonts/Inter';
import {loadFont as loadPoppins} from '@remotion/google-fonts/Poppins';
import content from './content.json';
import voTiming from './vo-timing.json';

// ---------------------------------------------------------------------------
// Editable text, colors, tile maps and timing live in content.json (brand:
// DataEntropy guideline). vo-timing.json is generated by `npm run srt`.
// All motion is keyed to scene start frames, so moving a scene's `start`
// shifts its animations with it.
// ---------------------------------------------------------------------------

const {fontFamily} = loadFont('normal', {weights: ['400', '500', '600', '700'], subsets: ['latin']});
const FONT = `${fontFamily}, Arial, sans-serif`;
const LOGO_FONT = `${loadPoppins('normal', {weights: ['700'], subsets: ['latin']}).fontFamily}, ${FONT}`;

const C = content.colors;
const L = content.labels;
const FPS = content.fps;
const END = content.durationSeconds * FPS;
const S = content.scenes.map((s) => Math.round(s.start * FPS)); // scene start frames
const sceneEnd = (i: number) => (i + 1 < S.length ? S[i + 1] : END);

// Screen layout (brand safe area: 10% top, 18% bottom, 7% sides).
const SAFE = {left: 76, right: 1004};
const HEADLINE_Y = 250;
const CONTENT_CY = 890; // screen y the camera centers content on
const SUB_BOTTOM = 1560;

type Ease = (t: number) => number;
const EASE = {
	out: Easing.bezier(0.22, 1, 0.36, 1),
	inOut: Easing.bezier(0.645, 0.045, 0.355, 1),
	in: Easing.bezier(0.55, 0.055, 0.675, 0.19),
	linear: (t: number) => t,
};

// Keyframe track: kf(frame, [f0, f1, ...], [v0, v1, ...], easing), clamped.
const kf = (f: number, frames: number[], values: number[], easing: Ease | Ease[] = EASE.inOut) => {
	if (f <= frames[0]) return values[0];
	const i = frames.findIndex((_, k) => k + 1 < frames.length && f < frames[k + 1]);
	if (i < 0) return values[values.length - 1];
	const e = Array.isArray(easing) ? easing[i] : easing;
	return values[i] + (values[i + 1] - values[i]) * e((f - frames[i]) / (frames[i + 1] - frames[i]));
};
const enter = (f: number, frames: number[], values: number[]) => kf(f, frames, values, EASE.out);

const mixColor = (a: string, b: string, t: number) => {
	const p = (h: string) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
	const [x, y] = [p(a), p(b)];
	return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, '0')).join('');
};

const parseMarked = (s: string) =>
	s.split(/(\*[^*]+\*)/).flatMap((part) => {
		const hl = part.startsWith('*');
		return part.replaceAll('*', '').split(/\s+/).filter(Boolean).map((w) => ({w, hl}));
	});
const spaced = (w: string, k: number) => (k > 0 && !/^[?.,!:;]/.test(w) ? ' ' : '') + w;

// ---------------------------------------------------------------------------
// World layout (world = screen coordinates when the camera is at 540, 890, 1):
// one picture frame, a step dial below it, the AI pill under the dial.
// ---------------------------------------------------------------------------

const N = 16;
const TILE = 40;
const COUNT = N * N;
const FRAME = {x: 220, y: 470, size: N * TILE};
const DIAL = {y: 1220, x0: 330, step: 100};
const PILL = {x: 540, y: 1330, w: 200, h: 80};
const CHIP = {x: 540, y: 395, w: 300, h: 74};
const OLD = {x: -410, y: 580, size: 420}; // the practice cat's small frame in the comparison
const LOGO = {barW: 66, gap: 22, heights: [96, 156, 212, 276], base: 700, wordY: 832, wordSize: 104};
const LOGO_LEFT = 540 - (LOGO.heights.length * (LOGO.barW + LOGO.gap) - LOGO.gap) / 2;

const col = (i: number) => i % N;
const row = (i: number) => Math.floor(i / N);
const cx = (i: number) => FRAME.x + col(i) * TILE + TILE / 2;
const cy = (i: number) => FRAME.y + row(i) * TILE + TILE / 2;
const dist = (i: number) => Math.hypot(col(i) - 7.5, row(i) - 7.5);
const ALL = Array.from({length: COUNT}, (_, i) => i);

// Seeded randomness: the same value for a tile on every frame and every render.
const rnd = (tag: string, i: number) => random(`${content.noiseSeed}-${tag}-${i}`);

const KEY: Record<string, string> = {'.': C.lavender, N: C.navy, W: C.card, V: C.violet, P: C.purple};
const toMap = (rows: string[]) => {
	if (rows.length !== N || rows.some((r) => r.length !== N || [...r].some((ch) => !KEY[ch]))) throw new Error('tile map must be 16 rows of 16 known characters');
	return rows.flatMap((r) => [...r].map((ch) => KEY[ch]));
};
const CAT_A = toMap(content.practiceCat);
const CAT_B = toMap(content.generatedCat);
const BLANK = C.card;

// Static is made of brand colors only.
const NOISE_COLORS = [C.navy, C.violet, C.purple, C.card];
const noise = (variant: string) => ALL.map((i) => NOISE_COLORS[Math.floor(rnd(variant, i) * NOISE_COLORS.length)]);
const NOISE_HOOK = noise('hook');
const NOISE_PRACTICE = noise('practice');
const NOISE_GEN = noise('generate');

// A muddled blob: what one big jump produces.
const BLOB_COLORS = [C.lavender, C.purple, C.lavender, C.violet, C.navy];
const BLOB = ALL.map((i) => (dist(i) + (rnd('blob-edge', i) - 0.5) * 3 < 5 ? BLOB_COLORS[Math.floor(rnd('blob', i) * BLOB_COLORS.length)] : null));

// The few speckles cleaned up in the close-up (top-left corner of the frame).
const SPECK = [[2, 2], [4, 2], [3, 3], [5, 3], [2, 4], [4, 4], [3, 5]].map(([c, r]) => r * N + c);
const SPECK_C = {x: FRAME.x + 4 * TILE, y: FRAME.y + 4 * TILE, r: 118};

// Noise level per dial notch: a tile is static when its rank is below the level.
const LEVELS = content.noiseLevels;
const RANK_A = ALL.map((i) => rnd('rank', i));
// For the new cat, backdrop and fur clear first, then ears and scarf, then the outline.
const RANK_B = (() => {
	const pri = (i: number) => (CAT_B[i] === C.navy ? 0 : CAT_B[i] === C.violet || CAT_B[i] === C.purple ? 1 : 2);
	const order = [...ALL].sort((a, b) => pri(a) + rnd('rankB', a) - (pri(b) + rnd('rankB', b)));
	const rank: number[] = [];
	order.forEach((i, k) => (rank[i] = k / COUNT));
	return rank;
})();
const band = (rank: number[], lo: number, hi: number) => ALL.filter((i) => rank[i] >= LEVELS[lo] && rank[i] < LEVELS[hi] + (hi === LEVELS.length - 1 ? 1 : 0));

// Key frames of the story.
const FWD_T = [S[4] + 20, S[4] + 76, S[5] + 10, S[5] + 50]; // each added noise step
const LIFT_T = S[7] + 12; // the guessed noise is taken away
const GEN_T = [0, 1, 2, 3].map((k) => S[10] + 12 + k * 32); // each cleared step while generating
const GUESS = band(RANK_A, 1, 2);
const liftDelay = (i: number) => rnd('lift', i) * 18;
const LIFTS = [
	{at: LIFT_T, tiles: GUESS},
	...GEN_T.map((at, k) => ({at, tiles: band(RANK_B, 3 - k, 4 - k).filter((i) => rnd('fly', i) < 0.45)})),
];
const LIFT_PATH = [{x: 995, y: 1010}, {x: 995, y: 1340}, {x: PILL.x + 70, y: PILL.y}]; // down the arrow, into the pill

const BRUSH = {t0: S[2] + 100, dur: 36, x0: 270, x1: 500};
const brushX = (f: number) => kf(f, [BRUSH.t0, BRUSH.t0 + BRUSH.dur], [BRUSH.x0, BRUSH.x1]);
const brushHit = (i: number) => {
	let d = 0;
	while (d < BRUSH.dur && brushX(BRUSH.t0 + d) < cx(i)) d++;
	return d;
};

// Tile color changes, in time order. Every change is a flip in place.
type Step = {at: number; delay: (i: number) => number; to: (i: number) => string | null};
const only = (tiles: number[], color: (i: number) => string) => {
	const set = new Set(tiles);
	return (i: number) => (set.has(i) ? color(i) : null);
};
const FLIP = 18;
const STEPS: Step[] = [
	{at: S[0] + 45, delay: (i) => dist(i) * 3, to: (i) => CAT_A[i]},
	{at: S[1] + 4, delay: (i) => (11 - dist(i)) * 1.5, to: () => BLANK},
	{at: S[1] + 50, delay: (i) => rnd('blob-delay', i) * 12, to: (i) => BLOB[i]},
	{at: S[2] + 2, delay: (i) => rnd('blob-delay', i) * 10, to: () => BLANK},
	{at: S[2] + 25, delay: (i) => rnd('speck', i) * 14, to: only(SPECK, (i) => NOISE_COLORS[SPECK.indexOf(i) % 3])},
	{at: BRUSH.t0, delay: brushHit, to: only(SPECK, () => BLANK)},
	{at: S[3] + 8, delay: (i) => row(i) * 3 + col(i) * 0.4, to: (i) => CAT_A[i]},
	...FWD_T.map((at, k) => ({at, delay: (i: number) => rnd('fwd', i) * 12, to: only(band(RANK_A, k, k + 1), (i) => NOISE_PRACTICE[i])})),
	{at: S[6] + 6, delay: (i) => rnd('back', i) * 14, to: only(band(RANK_A, 2, 4), (i) => CAT_A[i])},
	{at: LIFT_T, delay: liftDelay, to: only(GUESS, (i) => CAT_A[i])},
	{at: S[9] + 12, delay: (i) => rnd('regen', i) * 22, to: (i) => NOISE_GEN[i]},
	...GEN_T.map((at, k) => ({at, delay: liftDelay, to: only(band(RANK_B, 3 - k, 4 - k), (i) => CAT_B[i])})),
];
const tileAt = (f: number, i: number) => {
	let color = NOISE_HOOK[i];
	let from = color;
	let p = 1;
	for (const s of STEPS) {
		const to = s.to(i);
		if (to === null || to === color) continue;
		const start = s.at + s.delay(i);
		if (f < start) break;
		from = color;
		color = to;
		p = Math.min(1, (f - start) / FLIP);
	}
	return {from, color, p};
};

// Dial knob: [start frame, frames, notch it moves to]. It always matches the static in the frame.
const KNOB_MOVES = [
	...FWD_T.map((t, k) => [t, 18, k + 1]),
	[S[6] + 4, 30, 2],
	[S[7] + 60, 18, 1],
	[S[9] + 10, 30, 4],
	...GEN_T.map((t, k) => [t, 18, 3 - k]),
];
const knobAt = (f: number) => KNOB_MOVES.reduce((v, [t, d, to]) => (f <= t ? v : v + (to - v) * EASE.inOut(Math.min(1, (f - t) / d))), 0);

// ---------------------------------------------------------------------------
// Camera: close on the frame, out to the dial and AI pill, in on a corner,
// back out to the wall.
// ---------------------------------------------------------------------------

const camera = (f: number) => {
	const t = [S[1] - 10, S[1] + 25, S[2] - 5, S[2] + 30, S[3], S[3] + 40, S[8], S[8] + 30, S[9], S[9] + 30, S[11], S[11] + 40, S[12], S[12] + 30];
	return {
		x: kf(f, t, [540, 450, 450, 370, 370, 540, 540, 540, 540, 540, 540, 225, 225, 540]),
		y: kf(f, t, [790, 790, 790, 625, 625, 890, 890, 850, 850, 840, 840, 820, 820, 890]),
		s: kf(f, t, [1.25, 1, 1, 2.2, 2.2, 1, 1, 0.82, 0.82, 0.92, 0.92, 0.7, 0.7, 1]),
	};
};

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

const draw = (p: number) => ({pathLength: 1, strokeDasharray: '1 1', strokeDashoffset: 1 - p, opacity: p > 0 ? 1 : 0});

const ArrowHead: React.FC<{x: number; y: number; angle: number; color: string; w: number; size?: number; opacity: number}> = ({x, y, angle, color, w, size = 20, opacity}) => (
	<path d={`M ${-size} ${-size * 0.62} L 0 0 L ${-size} ${size * 0.62}`} transform={`translate(${x} ${y}) rotate(${angle})`}
		fill="none" stroke={color} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" opacity={opacity} />
);

// The same 256 tiles for the whole video; in the last scene they regroup into the logo's four columns.
const Tiles: React.FC<{f: number}> = ({f}) => {
	const a = S[12];
	return (
		<g>
			{ALL.map((i) => {
				const {from, color, p} = tileAt(f, i);
				const e = EASE.inOut(p);
				const sx = Math.abs(Math.cos(e * Math.PI));
				let fill = e < 0.5 ? from : color;
				let x = cx(i);
				let y = cy(i);
				let size = TILE + 2; // slight overdraw hides seams between tiles
				let o = 1;
				if (f > a) {
					const k = Math.floor(col(i) / 4);
					const d = rnd('regroup', i) * 6;
					const g = kf(f, [a + 4 + d, a + 32 + d], [0, 1]);
					x += (LOGO_LEFT + k * (LOGO.barW + LOGO.gap) + 14 + rnd('rx', i) * 38 - x) * g;
					y += (LOGO.base - 52 + rnd('ry', i) * 38 - y) * g;
					size -= 24 * g;
					fill = mixColor(fill, C.purple, g);
					o = kf(f, [a + 34 + k * 7, a + 44 + k * 7], [1, 0], EASE.in);
					if (o <= 0) return null;
				}
				const w = size * sx;
				return <rect key={i} x={x - w / 2} y={y - size / 2} width={w} height={size} fill={fill} opacity={o} />;
			})}
		</g>
	);
};

const PictureFrame: React.FC<{f: number; rest: number}> = ({f, rest}) => {
	const box = {x: FRAME.x - 6, y: FRAME.y - 6, width: FRAME.size + 12, height: FRAME.size + 12, rx: 20};
	return (
		<g>
			<rect {...box} fill={C.lavenderTint} filter="url(#soft)" opacity={rest} />
			<Tiles f={f} />
			<rect {...box} fill="none" stroke={C.navy} strokeWidth={6} opacity={rest} />
		</g>
	);
};

// Scene 2: one big jump straight to a picture fails.
const OneJump: React.FC<{f: number}> = ({f}) => {
	const o = kf(f, [S[2], S[2] + 10], [1, 0], EASE.in);
	if (f < S[1] + 26 || o <= 0) return null;
	const leap = enter(f, [S[1] + 28, S[1] + 46], [0, 1]);
	const cross = enter(f, [S[1] + 80, S[1] + 94], [0, 1]);
	const label = enter(f, [S[1] + 32, S[1] + 48], [0, 1]);
	return (
		<g opacity={o}>
			<path d="M -15 790 L 196 790" fill="none" stroke={C.violet} strokeWidth={6} strokeLinecap="round" {...draw(leap)} />
			<ArrowHead x={198} y={790} angle={0} color={C.violet} w={6} opacity={leap > 0.9 ? 1 : 0} />
			<text x={95} y={742 + (1 - label) * 24} fontSize={36} fontWeight={700} textAnchor="middle" fill={C.navy} opacity={label}>{L.jump}</text>
			{[1, -1].map((d, k) => (
				<path key={d} d={`M 55 ${790 - 36 * d} L 127 ${790 + 36 * d}`} fill="none" stroke={C.navy} strokeWidth={7} strokeLinecap="round"
					{...draw(enter(f, [S[1] + 80 + k * 6, S[1] + 94 + k * 6], [0, 1]) * (cross > 0 ? 1 : 0))} />
			))}
		</g>
	);
};

// Scene 3: a ring names the speckles "noise", then a brush cleans them up.
const NoiseCloseUp: React.FC<{f: number}> = ({f}) => {
	const o = kf(f, [S[3], S[3] + 10], [1, 0], EASE.in);
	if (f < S[2] + 45 || o <= 0) return null;
	const ring = enter(f, [S[2] + 50, S[2] + 74], [0, 1]);
	const label = enter(f, [S[2] + 64, S[2] + 80], [0, 1]);
	const brushO = kf(f, [BRUSH.t0 - 16, BRUSH.t0 - 2, BRUSH.t0 + BRUSH.dur + 4, BRUSH.t0 + BRUSH.dur + 14], [0, 1, 1, 0], [EASE.out, EASE.linear, EASE.in]);
	const u = 1 / 2.2; // this scene is seen at 2.2x zoom
	return (
		<g opacity={o}>
			<circle cx={SPECK_C.x} cy={SPECK_C.y} r={SPECK_C.r} fill="none" stroke={C.violet} strokeWidth={5 * u} strokeLinecap="round"
				transform={`rotate(-90 ${SPECK_C.x} ${SPECK_C.y})`} {...draw(ring)} />
			<text x={SPECK_C.x} y={SPECK_C.y + SPECK_C.r + 24 + (1 - label) * 10} fontSize={38 * u} fontWeight={700} textAnchor="middle" fill={C.navy} opacity={label}>{L.noise}</text>
			<g transform={`translate(${brushX(f)} ${SPECK_C.y}) rotate(84)`} opacity={brushO}>
				<rect x={-17} y={-150} width={34} height={110} rx={17} fill={C.card} stroke={C.navy} strokeWidth={5 * u} />
				<rect x={-84} y={-46} width={168} height={18} rx={4} fill={C.navy} />
				<rect x={-80} y={-30} width={160} height={30} rx={5} fill={C.violet} stroke={C.navy} strokeWidth={4 * u} />
			</g>
		</g>
	);
};

// The step dial: cat icon (picture) on the left, speckles (static) on the right.
const StepDial: React.FC<{f: number}> = ({f}) => {
	const o = kf(f, [S[11], S[11] + 12], [1, 0], EASE.in);
	if (f < S[3] + 44 || o <= 0) return null;
	const track = enter(f, [S[3] + 45, S[3] + 75], [0, 1]);
	const icons = enter(f, [S[3] + 68, S[3] + 86], [0, 1]);
	const knob = enter(f, [S[3] + 76, S[3] + 94], [0, 1]);
	const x1 = DIAL.x0 + 4 * DIAL.step;
	return (
		<g opacity={o}>
			<path d={`M ${DIAL.x0} ${DIAL.y} L ${x1} ${DIAL.y}`} fill="none" stroke={C.navy} strokeWidth={5} strokeLinecap="round" {...draw(track)} />
			{[0, 1, 2, 3, 4].map((k) => {
				const n = enter(f, [S[3] + 50 + k * 5, S[3] + 64 + k * 5], [0, 1]);
				return <circle key={k} cx={DIAL.x0 + k * DIAL.step} cy={DIAL.y} r={10 * (0.96 + 0.04 * n)} fill={C.navy} opacity={n} />;
			})}
			<g transform={`translate(${DIAL.x0 - 62} ${DIAL.y})`} opacity={icons}>
				<path d="M -22 -28 L -8 -15 L 8 -15 L 22 -28 L 22 4 Q 22 22 0 22 Q -22 22 -22 4 Z" fill={C.card} stroke={C.navy} strokeWidth={5} strokeLinejoin="round" />
				<circle cx={-8} cy={2} r={3.5} fill={C.navy} />
				<circle cx={8} cy={2} r={3.5} fill={C.navy} />
			</g>
			<g transform={`translate(${x1 + 62} ${DIAL.y}) scale(1.25)`} opacity={icons}>
				{[C.navy, C.violet, C.purple, C.violet, C.navy].map((c, k) => (
					<rect key={k} x={[-20, 6, -7, -20, 6][k]} y={[-20, -20, -7, 6, 6][k]} width={14} height={14} rx={2} fill={c} />
				))}
			</g>
			<circle cx={DIAL.x0 + knobAt(f) * DIAL.step} cy={DIAL.y} r={22 * (0.96 + 0.04 * knob)} fill={C.violet} stroke={C.card} strokeWidth={5} opacity={knob} />
		</g>
	);
};

const AddNoiseArrow: React.FC<{f: number}> = ({f}) => {
	const o = kf(f, [S[6], S[6] + 10], [1, 0], EASE.in);
	if (f < S[4] + 28 || o <= 0) return null;
	const p = enter(f, [S[4] + 30, S[4] + 50], [0, 1]);
	const label = enter(f, [S[4] + 40, S[4] + 56], [0, 1]);
	return (
		<g opacity={o}>
			<path d="M 400 1296 L 676 1296" fill="none" stroke={C.purple} strokeWidth={5} strokeLinecap="round" {...draw(p)} />
			<ArrowHead x={678} y={1296} angle={0} color={C.purple} w={5} size={18} opacity={p > 0.9 ? 1 : 0} />
			<text x={540} y={1352 + (1 - label) * 16} fontSize={36} fontWeight={700} textAnchor="middle" fill={C.navy} opacity={label}>{L.addNoise}</text>
		</g>
	);
};

const AIPill: React.FC<{f: number}> = ({f}) => {
	const o = kf(f, [S[11], S[11] + 12], [1, 0], EASE.in);
	if (f < S[6] + 24 || o <= 0) return null;
	const rise = enter(f, [S[6] + 24, S[6] + 44], [0, 1]);
	// A small swell each time a noise cluster drops in.
	const swell = Math.max(...LIFTS.map(({at}) => kf(f, [at + 38, at + 46, at + 60], [0, 1, 0])));
	const {x, y, w, h} = PILL;
	return (
		<g opacity={o * rise} transform={`translate(${x} ${y + (1 - rise) * 24}) scale(${1 + swell * 0.05})`}>
			<rect x={-w / 2 - 16} y={-h / 2 - 16} width={w + 32} height={h + 32} rx={h / 2 + 16} fill={C.lavender} opacity={0.55} />
			<rect x={-w / 2} y={-h / 2} width={w} height={h} rx={h / 2} fill={C.navy} />
			<text y={15} fontSize={42} fontWeight={700} textAnchor="middle" fill="#fff">{L.ai}</text>
		</g>
	);
};

// Arrow linking the AI pill to the frame (right side).
const GuessArrow: React.FC<{f: number}> = ({f}) => {
	const p = f < S[9] ? enter(f, [S[6] + 40, S[6] + 65], [0, 1]) : enter(f, [S[10], S[10] + 25], [0, 1]);
	const o = f < S[9] ? kf(f, [S[8], S[8] + 12], [1, 0], EASE.in) : kf(f, [S[11], S[11] + 12], [1, 0], EASE.in);
	if (p <= 0 || o <= 0) return null;
	return (
		<g opacity={o}>
			<path d={`M ${PILL.x + PILL.w / 2 + 22} ${PILL.y} C 960 1340 960 1010 880 890`} fill="none" stroke={C.violet} strokeWidth={5} strokeLinecap="round" {...draw(p)} />
			<ArrowHead x={878} y={887} angle={-123.7} color={C.violet} w={5} size={18} opacity={p > 0.9 ? 1 : 0} />
		</g>
	);
};

// The AI's guess: the tiles the last step added get a violet outline.
const GuessOutlines: React.FC<{f: number}> = ({f}) => {
	if (f < S[6] + 60 || f > LIFT_T + 40) return null;
	return (
		<g>
			{GUESS.map((i) => {
				const d = rnd('guess', i) * 12;
				const o = enter(f, [S[6] + 62 + d, S[6] + 74 + d], [0, 1]) * kf(f, [LIFT_T + liftDelay(i), LIFT_T + liftDelay(i) + 8], [1, 0], EASE.in);
				// White under the violet keeps the outline readable on violet and purple tiles.
				return (
					<g key={i} opacity={o} fill="none">
						<rect x={cx(i) - 17} y={cy(i) - 17} width={34} height={34} stroke={C.card} strokeWidth={10} />
						<rect x={cx(i) - 17} y={cy(i) - 17} width={34} height={34} stroke={C.violet} strokeWidth={4} />
					</g>
				);
			})}
		</g>
	);
};

// Guessed noise tiles lift out of the frame and drop into the AI pill.
const NoiseCluster: React.FC<{f: number}> = ({f}) => (
	<g>
		{LIFTS.flatMap(({at, tiles}) =>
			f < at || f > at + 60 ? [] : tiles.map((i) => {
				const s = at + liftDelay(i);
				const p = kf(f, [s, s + 38], [0, 1]);
				if (p <= 0 || p >= 1) return null;
				const q = 1 - p;
				const [b0, b1, b2, b3] = [q * q * q, 3 * q * q * p, 3 * q * p * p, p * p * p];
				const x = b0 * cx(i) + b1 * LIFT_PATH[0].x + b2 * LIFT_PATH[1].x + b3 * LIFT_PATH[2].x;
				const y = b0 * cy(i) + b1 * LIFT_PATH[0].y + b2 * LIFT_PATH[1].y + b3 * LIFT_PATH[2].y;
				const size = TILE - 24 * p;
				return <rect key={`${at}-${i}`} x={x - size / 2} y={y - size / 2} width={size} height={size} rx={4} fill={C.purple} stroke={C.card} strokeWidth={2}
					opacity={kf(f, [s + 30, s + 38], [1, 0], EASE.in)} />;
			}),
		)}
	</g>
);

// Scene 9: other practice pictures fill with noise and clear again.
const MINI = {size: 170, y: 345, gap: 215, tile: 30};
const MINI_ICONS = [
	<g key="tree"><path d="M 0 60 L 0 22" /><path d="M 0 -58 L 46 22 L -46 22 Z" fill={C.lavenderTint} /></g>,
	<g key="house"><path d="M -38 -4 L -38 56 L 38 56 L 38 -4" fill={C.lavenderTint} /><path d="M -54 -2 L 0 -50 L 54 -2" /><path d="M -11 56 L -11 22 L 11 22 L 11 56" /></g>,
	<g key="bike"><circle cx={-38} cy={28} r={24} /><circle cx={38} cy={28} r={24} /><path d="M -38 28 L -14 -12 L 22 -12 L 38 28 M -14 -12 L 4 28 L 22 -12 M -24 -26 L -6 -26 M 22 -12 L 18 -32 L 34 -34" /></g>,
	<g key="cup"><path d="M -38 -32 L 38 -32 L 29 48 L -29 48 Z" fill={C.lavenderTint} /><path d="M 36 -14 C 68 -14 68 30 31 30" /></g>,
];
const MiniFrameRow: React.FC<{f: number}> = ({f}) => {
	if (f < S[8] + 8 || f > S[9] + 18) return null;
	const dx = enter(f, [S[8] + 10, S[8] + 36], [700, 0]) + kf(f, [S[9], S[9] + 16], [0, -700], EASE.in);
	const o = enter(f, [S[8] + 10, S[8] + 30], [0, 1]) * kf(f, [S[9], S[9] + 16], [1, 0], EASE.in);
	return (
		<g opacity={o} transform={`translate(${dx} 0)`}>
			{MINI_ICONS.map((icon, k) => (
				<g key={k} transform={`translate(${540 + (k - 1.5) * MINI.gap} ${MINI.y})`}>
					<rect x={-MINI.size / 2} y={-MINI.size / 2} width={MINI.size} height={MINI.size} rx={18} fill={C.card} />
					<g fill="none" stroke={C.navy} strokeWidth={6} strokeLinecap="round" strokeLinejoin="round">{icon}</g>
					{Array.from({length: 25}, (_, j) => {
						const d = rnd(`mini-${k}`, j) * 10;
						const tIn = S[8] + 34 + k * 8 + d;
						const tOut = S[8] + 62 + k * 8 + d;
						const sx = kf(f, [tIn, tIn + FLIP], [0, 1]) - kf(f, [tOut, tOut + FLIP], [0, 1]);
						if (sx <= 0) return null;
						const w = (MINI.tile + 2) * sx;
						return <rect key={j} x={-60 + (j % 5) * MINI.tile - w / 2} y={-75 + Math.floor(j / 5) * MINI.tile} width={w} height={MINI.tile + 2}
							fill={NOISE_COLORS[Math.floor(rnd(`mini-c-${k}`, j) * 4)]} />;
					})}
					<rect x={-MINI.size / 2} y={-MINI.size / 2} width={MINI.size} height={MINI.size} rx={18} fill="none" stroke={C.navy} strokeWidth={5} />
				</g>
			))}
		</g>
	);
};

const Counter: React.FC<{f: number}> = ({f}) => {
	const o = enter(f, [S[8] + 28, S[8] + 42], [0, 1]) * kf(f, [S[9], S[9] + 10], [1, 0], EASE.in);
	if (o <= 0) return null;
	const p = kf(f, [S[8] + 36, S[8] + 86], [0, 1], EASE.linear);
	return (
		<text x={PILL.x + PILL.w / 2 + 40} y={PILL.y + 16} fontSize={46} fontWeight={700} fill={C.navy} opacity={o}>
			{p < 1 ? Math.round(10 ** (p * 6)).toLocaleString('en-US') : L.counterEnd}
		</text>
	);
};

// Scene 10: the prompt is typed and linked to the AI pill (left side).
const PromptChip: React.FC<{f: number}> = ({f}) => {
	const o = kf(f, [S[11], S[11] + 12], [1, 0], EASE.in);
	if (f < S[9] + 38 || o <= 0) return null;
	const a = enter(f, [S[9] + 40, S[9] + 58], [0, 1]);
	const typed = Math.floor(kf(f, [S[9] + 62, S[9] + 82], [0, content.prompt.length], EASE.linear));
	const link = enter(f, [S[9] + 84, S[9] + 110], [0, 1]);
	const {x, y, w, h} = CHIP;
	return (
		<g opacity={o}>
			<path d={`M ${x - w / 2} ${y} C -10 ${y} -10 ${PILL.y} ${PILL.x - PILL.w / 2 - 26} ${PILL.y}`} fill="none" stroke={C.violet} strokeWidth={5} strokeLinecap="round" {...draw(link)} />
			<ArrowHead x={PILL.x - PILL.w / 2 - 22} y={PILL.y} angle={0} color={C.violet} w={5} size={18} opacity={link > 0.9 ? 1 : 0} />
			<g opacity={a} transform={`translate(0 ${(1 - a) * 24})`}>
				<rect x={x - w / 2} y={y - h / 2} width={w} height={h} rx={20} fill={C.card} stroke={C.navy} strokeWidth={5} />
				<circle cx={x - w / 2 + 44} cy={y} r={10} fill={C.violet} />
				<text x={x - w / 2 + 78} y={y + 14} fontSize={40} fontWeight={600} fill={C.navy}>{content.prompt.slice(0, typed)}</text>
			</g>
		</g>
	);
};

// Scene 12: the practice cat beside the new cat, and a check of the details.
const Compare: React.FC<{f: number; rest: number}> = ({f, rest}) => {
	if (f < S[11] + 18 || rest <= 0) return null;
	const old = enter(f, [S[11] + 20, S[11] + 44], [0, 1]);
	const k = OLD.size / (FRAME.size + 12);
	const paw = {x: cx(content.extraToe.row * N + content.extraToe.col), y: cy(content.extraToe.row * N + content.extraToe.col)};
	const t = [S[11] + 76, S[11] + 112];
	const mx = kf(f, t, [770, paw.x]);
	const my = kf(f, t, [620, paw.y]);
	const lens = enter(f, [S[11] + 62, S[11] + 80], [0, 1]);
	const badge = enter(f, [S[11] + 116, S[11] + 136], [0, 1]);
	const R = 92;
	return (
		<g opacity={rest}>
			<g opacity={old} transform={`translate(${OLD.x} ${OLD.y + (1 - old) * 30}) scale(${k})`}>
				<rect width={FRAME.size + 12} height={FRAME.size + 12} rx={20} fill={C.lavenderTint} filter="url(#soft)" />
				{ALL.map((i) => <rect key={i} x={6 + col(i) * TILE} y={6 + row(i) * TILE} width={TILE + 3} height={TILE + 3} fill={CAT_A[i]} />)}
				<rect width={FRAME.size + 12} height={FRAME.size + 12} rx={20} fill="none" stroke={C.navy} strokeWidth={5 / 0.7 / k} />
			</g>
			<g fill="none" stroke={C.violet} strokeWidth={8} strokeLinecap="round">
				{['M 68 772 L 156 772', 'M 68 808 L 156 808', 'M 90 836 L 134 744'].map((d, n) => (
					<path key={n} d={d} {...draw(enter(f, [S[11] + 50, S[11] + 66], [0, 1]))} />
				))}
			</g>
			<g opacity={lens}>
				<path d={`M ${mx + R * 0.71} ${my + R * 0.71} l 56 56`} stroke={C.navy} strokeWidth={14} strokeLinecap="round" />
				<circle cx={mx} cy={my} r={R} fill="none" stroke={C.navy} strokeWidth={8} />
			</g>
			<g opacity={badge} transform={`translate(540 ${1262 + (1 - badge) * 30})`}>
				<rect x={-240} y={-50} width={480} height={100} rx={28} fill={C.card} stroke={C.violet} strokeWidth={6} filter="url(#soft)" />
				<text y={17} fontSize={50} fontWeight={600} textAnchor="middle" fill={C.navy}>{L.badge}</text>
			</g>
		</g>
	);
};

// Headline: left-aligned, masked reveal line by line, *words* in brand violet.
const Headline: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			if (!sc.headline) return null;
			const a = S[i];
			const b = sceneEnd(i);
			const out = kf(f, [b - 8, b], [1, 0], EASE.in);
			if (f < a || out <= 0) return null;
			return (
				<g key={i} opacity={out}>
					{sc.headline.split('\n').map((line, li) => {
						const y = HEADLINE_Y + li * 72;
						const rise = enter(f, [a + li * 4, a + 18 + li * 4], [74, 0]);
						return (
							<g key={li}>
								<clipPath id={`hl-${i}-${li}`}>
									<rect x={0} y={y - 62} width={1080} height={80} />
								</clipPath>
								<text x={SAFE.left} y={y + rise} clipPath={`url(#hl-${i}-${li})`} fontSize={58} fontWeight={700} fill={C.navy}>
									{parseMarked(line).map(({w, hl}, k) => (
										<tspan key={k} fill={hl ? C.violet : C.navy}>{spaced(w, k)}</tspan>
									))}
								</text>
							</g>
						);
					})}
				</g>
			);
		})}
	</>
);

// Subtitles: navy bar in the lower safe area, word-group reveal synced to the voiceover.
const Subtitles: React.FC<{f: number}> = ({f}) => (
	<>
		{content.scenes.map((sc, i) => {
			const start = sc.voStart * FPS;
			const dur = (voTiming[i] ?? 3) * FPS;
			const end = Math.min(sceneEnd(i) - 2, start + dur + 18);
			const o = kf(f, [start - 4, start + 4, end - 6, end], [0, 1, 1, 0]);
			if (o <= 0) return null;
			const words = parseMarked(sc.voiceover);
			const perLine = words.length > 6 ? Math.ceil(words.length / 2) : words.length;
			const lines = [words.slice(0, perLine), words.slice(perLine)].filter((l) => l.length);
			const h = 34 + lines.length * 54;
			let n = 0;
			return (
				<g key={i} opacity={o}>
					<rect x={SAFE.left} y={SUB_BOTTOM - h} width={SAFE.right - SAFE.left} height={h} rx={20} fill={C.navy} fillOpacity={0.88} />
					{lines.map((line, li) => (
						<text key={li} x={540} y={SUB_BOTTOM - h + 56 + li * 54} fontSize={40} fontWeight={600} textAnchor="middle">
							{line.map(({w, hl}, k) => {
								// Words reveal in groups of three, paced across the spoken line.
								const group = Math.floor(n++ / 3);
								const at = start + (group * 3 * dur) / words.length;
								return (
									<tspan key={k} fill={hl ? C.lavender : '#fff'} fillOpacity={enter(f, [at, at + 8], [0.25, 1])}>
										{spaced(w, k)}
									</tspan>
								);
							})}
						</text>
					))}
				</g>
			);
		})}
	</>
);

// Outro: the tiles have gathered into four columns; the logo bars grow out of them,
// then the wordmark, tagline and one CTA.
const Outro: React.FC<{f: number}> = ({f}) => {
	const a = S[12];
	if (f < a) return null;
	const {barW, gap, heights, base} = LOGO;
	const symbolW = heights.length * barW + (heights.length - 1) * gap;
	const left = LOGO_LEFT;
	const top = base - heights[heights.length - 1];
	const word = enter(f, [a + 64, a + 84], [0, 1]);
	const glow = kf(f, [a + 78, a + 87, a + 96], [0, 1, 0.35]);
	const tag = enter(f, [a + 78, a + 94], [0, 1]);
	const cta = enter(f, [a + 88, a + 106], [0, 1]);
	const arrow = kf(f, [a + 102, a + 120], [0, 10], EASE.inOut);
	return (
		<g>
			<linearGradient id="logoBars" gradientUnits="userSpaceOnUse" x1={left} y1={top} x2={left + symbolW} y2={base}>
				<stop offset="0" stopColor={C.lavender} />
				<stop offset="0.55" stopColor={C.purple} />
				<stop offset="1" stopColor={C.violet} />
			</linearGradient>
			<g filter={glow > 0.05 ? 'url(#glow)' : undefined}>
				{heights.map((bh, k) => {
					const g = enter(f, [a + 34 + k * 7, a + 52 + k * 7], [0, 1]);
					const h = Math.max(barW * g, bh * g); // grows from a rounded stub
					return <rect key={k} x={left + k * (barW + gap)} y={base - h} width={barW} height={h} rx={barW / 2} fill="url(#logoBars)" opacity={g > 0 ? 1 : 0} />;
				})}
			</g>
			<clipPath id="wordmark">
				<rect x={540 - 400} y={LOGO.wordY - 110} width={800 * word} height={150} />
			</clipPath>
			<text x={540} y={LOGO.wordY} clipPath="url(#wordmark)" fontFamily={LOGO_FONT} fontSize={LOGO.wordSize} fontWeight={700}
				textAnchor="middle" fill={C.navy} letterSpacing={-1}>
				Data<tspan fill={C.purple}>E</tspan>ntropy
			</text>
			<text x={540} y={935 + (1 - tag) * 24} fontSize={34} fontWeight={500} textAnchor="middle" fill={C.muted} opacity={tag}>{content.brand.tagline}</text>
			<g opacity={cta} transform={`translate(0 ${(1 - cta) * 24})`}>
				<rect x={260} y={1000} width={560} height={100} rx={20} fill={C.violet} filter="url(#soft)" />
				<text x={520} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">{content.brand.cta}</text>
				<text x={745 + arrow} y={1063} fontSize={38} fontWeight={600} textAnchor="middle" fill="#fff">→</text>
			</g>
		</g>
	);
};

// ---------------------------------------------------------------------------

export const DiffusionVideo: React.FC = () => {
	const f = useCurrentFrame();
	const base = camera(f);
	// A slow breathing zoom (6 s sine loop) keeps the picture alive while the narrator talks over a held frame.
	const cam = {...base, s: base.s * (1 + 0.015 * Math.sin((f / 180) * 2 * Math.PI))};
	const rest = kf(f, [S[12], S[12] + 12], [1, 0], EASE.in); // everything but the tiles leaves before the logo

	return (
		<AbsoluteFill style={{backgroundColor: C.background, fontFamily: FONT}}>
			<svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{fontFamily: FONT}}>
				<defs>
					<filter id="soft" x="-30%" y="-30%" width="160%" height="170%">
						<feDropShadow dx="0" dy="10" stdDeviation="14" floodColor={C.violet} floodOpacity="0.1" />
					</filter>
					<filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
						<feDropShadow dx="0" dy="0" stdDeviation="12" floodColor={C.violet} floodOpacity="0.35" />
					</filter>
					<pattern id="dots" width={48} height={48} patternUnits="userSpaceOnUse">
						<circle cx={24} cy={24} r={2} fill={C.grid} />
					</pattern>
					<linearGradient id="worldFade" x1="0" y1="0" x2="0" y2="1920" gradientUnits="userSpaceOnUse">
						<stop offset={340 / 1920} stopColor="#fff" stopOpacity={0} />
						<stop offset={400 / 1920} stopColor="#fff" />
						<stop offset={1390 / 1920} stopColor="#fff" />
						<stop offset={1440 / 1920} stopColor="#fff" stopOpacity={0} />
					</linearGradient>
					<mask id="worldMask" maskUnits="userSpaceOnUse" x={0} y={0} width={1080} height={1920}>
						<rect width={1080} height={1920} fill="url(#worldFade)" />
					</mask>
					<radialGradient id="lavGlow" cx="0.85" cy="0.1" r="0.7">
						<stop offset="0" stopColor={C.lavender} stopOpacity={0.35} />
						<stop offset="1" stopColor={C.lavender} stopOpacity={0} />
					</radialGradient>
				</defs>
				<rect width={1080} height={1920} fill="url(#lavGlow)" />
				<g mask="url(#worldMask)">
					<g transform={`translate(${540 - cam.x * cam.s} ${CONTENT_CY - cam.y * cam.s}) scale(${cam.s})`}>
						<rect x={-1600} y={-1200} width={4200} height={4200} fill="url(#dots)" opacity={rest} />
						<MiniFrameRow f={f} />
						<PromptChip f={f} />
						<PictureFrame f={f} rest={rest} />
						<GuessOutlines f={f} />
						<OneJump f={f} />
						<NoiseCloseUp f={f} />
						<GuessArrow f={f} />
						<NoiseCluster f={f} />
						<StepDial f={f} />
						<AddNoiseArrow f={f} />
						<AIPill f={f} />
						<Counter f={f} />
						<Compare f={f} rest={rest} />
					</g>
				</g>
				<Outro f={f} />
				<Headline f={f} />
				<Subtitles f={f} />
			</svg>
			{content.scenes.map((sc, i) => (
				<Sequence key={i} from={Math.round(sc.voStart * FPS)}>
					<Audio src={staticFile(`vo/scene-${i + 1}.wav`)} />
				</Sequence>
			))}
			<Audio src={staticFile('music.wav')} />
		</AbsoluteFill>
	);
};
